from typing import TypedDict, Unpack

from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class ThreadKwargs(TypedDict):
    cursor: str


class ThreadsMethods(BaseClient):
    """
    Методы группы 'Треды' из https://im-docs.corp.mail.ru/
    """

    @api_version_check(min_version=57)
    @tracer.start_as_current_span("threads.rapi_thread_add")
    def rapi_thread_add(self, chatId: str, messageId: int, _type: str = "message") -> dict:
        """
        Метод для создания нового треда.

        :param chatId: Идентификатор родительского чата chatId
        :param messageId: Message id родительского сообщения
        :param _type: Тип родителя треда.
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/thread/add",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "parentTopic": {
                        "chatId": chatId,
                        "messageId": messageId,
                        "type": _type,
                    },
                },
            },
        )

    @api_version_check(min_version=62)
    @tracer.start_as_current_span("threads.rapi_thread_get")
    def rapi_thread_get(self, threadId: str):
        """
        Получить информацию о треде

        Метод для получения информации о треде.
        В информацию входят parentTopic, количество подписчиков,
        великолепная пятерка подписчиков, а так же поле указывающее
        является ли запрашивающий подписчиком треда.

        Первым в великолепной пятерке подписчиков будет отправитель,
        если он является подписчиком треда.
        """
        return self.post(
            "rapi/thread/get",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"threadId": threadId},
            },
        )

    @api_version_check(min_version=57)
    @tracer.start_as_current_span("threads.rapi_thread_feed_get")
    def rapi_thread_feed_get(
        self, pageSize: int = 10, filter_type: str = "all", **kwargs: Unpack[ThreadKwargs]
    ) -> dict:
        """
        Получить поток тредов

        Метод для получения фида. Фид это список элементов.
        Пока элементы это только треды
        param cursor:
        """
        return self.post(
            "rapi/thread/feed/get",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "pageSize": pageSize,
                    **kwargs,
                    "filter": {"type": filter_type},
                },
            },
        )

    @api_version_check(min_version=62)
    @tracer.start_as_current_span("threads.rapi_thread_subscribe")
    def rapi_thread_subscribe(self, threadId: str):
        """
        Метод для подписки на тред. Тред появится в фиде тредов.
        """
        return self.post(
            "rapi/thread/subscribe",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"threadId": threadId},
            },
        )

    @api_version_check(min_version=62)
    @tracer.start_as_current_span("threads.rapi_thread_unsubscribe")
    def rapi_thread_unsubscribe(self, threadId: str):
        """
        Метод для отписки от треда. Тред удалится из фида тредов.
        """
        return self.post(
            "rapi/thread/unsubscribe",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {"threadId": threadId},
            },
        )

    @api_version_check(min_version=69)
    @tracer.start_as_current_span("threads.rapi_thread_subscribers_get")
    def rapi_thread_subscribers_get(self, thread_id: str, page_size: int = 10, **kwargs: Unpack[ThreadKwargs]):
        """
        Метод для получения подписчиков треда с использованием пагинации.
        Курсор и размер страницы конфликтуют.
        :param thread_id: Идентификатор группы
        :param page_size: Размер страницы для пагинации
        param cursor: Курсор пагинации, который вы получили из предыдущего запроса
        """
        return self.post(
            "rapi/thread/subscribers/get",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "threadId": thread_id,
                    "pageSize": page_size,
                    **kwargs,
                },
            },
        )

    @api_version_check(min_version=69)
    @tracer.start_as_current_span("threads.rapi_thread_subscribers_search")
    def rapi_thread_subscribers_search(
        self,
        thread_id: str,
        filter_keyword: str,
        page_size: int = 10,
        **kwargs: Unpack[ThreadKwargs],
    ):
        """
        Метод для поиска подписчиков треда с использованием пагинации.
        Курсор конфликтует с фильтром и размером страницы.
        :param thread_id: Идентификатор группы
        :param page_size: Размер страницы для пагинации
        param cursor: Курсор пагинации, который вы получили из предыдущего запроса
        :param filter_keyword: поисковый запрос
        """
        return self.post(
            "rapi/thread/subscribers/search",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "threadId": thread_id,
                    "pageSize": page_size,
                    **kwargs,
                    "filter": {"keyword": filter_keyword},
                },
            },
        )

    @api_version_check(min_version=74)
    @tracer.start_as_current_span("threads.rapi_thread_autosubscribe")
    def rapi_thread_autosubscribe(self, chatId: str, enable: bool = True, with_existing: bool = True):
        """
        Метод для автоподписки на новые треды чата
        """
        return self.post(
            "rapi/thread/autosubscribe",
            headers={"Content-Type": "application/json"},
            json={
                "reqId": self.getReqId(),
                "aimsid": self.aimsid,
                "params": {
                    "chatId": chatId,
                    "enable": enable,
                    "withExisting": with_existing,
                },
            },
        )
